        <button type="button" data-testid="claim-edit" onClick={() => act(() => setEditing(c.id))}>
          Edit
        </button>
      )}
      {status.isError && (
        <span data-testid="claim-error" role="alert">
          {' '}
          Not allowed: a {c.status} claim cannot make that status change.
        </span>
      )}
    </li>
  );
}
